// Service Worker for BaseTeam PWA
importScripts('https://storage.googleapis.com/workbox-cdn/releases/6.4.1/workbox-sw.js');

// Precache all the assets generated by your build process
workbox.precaching.precacheAndRoute(self.__WB_MANIFEST || []);

const { registerRoute } = workbox.routing;
const { NetworkFirst, StaleWhileRevalidate, NetworkOnly } = workbox.strategies;
const { BackgroundSyncPlugin } = workbox.backgroundSync;
const { ExpirationPlugin } = workbox.expiration;

workbox.setConfig({ debug: false });

// Background sync setup
const BACKGROUND_SYNC_QUEUE = 'background-sync-queue';

// Push notification constants
const NOTIFICATION_ICON = '/base-team-logo.jpg';
const NOTIFICATION_TITLE = 'BaseTeam';
const NOTIFICATION_OPTIONS = {
  body: 'You have new updates!',
  icon: NOTIFICATION_ICON,
  badge: '/base-team-logo.jpg',
  vibrate: [200, 100, 200, 100, 200, 100, 200],
  tag: 'base-team-notification',
  data: {
    dateOfArrival: Date.now(),
    primaryKey: 1
  },
  actions: [
    { action: 'view', title: 'View', icon: '/icons/eye.png' },
    { action: 'dismiss', title: 'Dismiss', icon: '/icons/x-mark.png' }
  ]
};

// Helper functions
const isApiRequest = (url) => url.pathname.startsWith('/v1/api/');
const isWriteOperation = (request) => 
  ['POST', 'PUT', 'PATCH', 'DELETE'].includes(request.method);

const CACHE_NAME = 'v1';
const OFFLINE_URL = '/offline.html';

// Install event - cache core files
self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE_NAME).then((cache) => {
      return cache.addAll([
        '/',
        '/index.html',
        '/manifest.json',
        '/offline.html',
        '/base-team-logo.jpg',
        '/favicon.ico',
        'https://fonts.googleapis.com/css?family=Inter:wght@300;400;500;600;700&display=swap',
        '/assets/index.ts',
      ]);
    })
  );
  self.skipWaiting();
});

// Listen for the 'install' event to show the update notification
self.addEventListener('install', (event) => {
  self.skipWaiting();
  const notifyClients = () => {
    self.clients.matchAll({ type: 'window' }).then(clients => {
      clients.forEach(client => {
        client.postMessage({
          type: 'SERVICE_WORKER_UPDATE',
          message: 'A new version is available!',
          timestamp: new Date().toISOString()
        });
      });
    });
  };
  event.waitUntil(notifyClients());
});

// Activate event - clean up old caches and take control of all clients immediately
self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((cacheNames) => {
      return Promise.all(
        cacheNames.map((cacheName) => {
          if (cacheName !== CACHE_NAME) {
            return caches.delete(cacheName);
          }
        })
      );
    }).then(() => self.clients.claim())
  );
});

// Listen for messages from the client
self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'SKIP_WAITING') {
    self.skipWaiting();
  }
});

// Handle push events
self.addEventListener('push', (event) => {
  let notificationData = NOTIFICATION_OPTIONS;
  if (event.data) {
    try {
      const data = event.data.json();
      notificationData = {
        ...NOTIFICATION_OPTIONS,
        ...data,
        data: {
          ...NOTIFICATION_OPTIONS.data,
          ...(data.data || {})
        }
      };
    } catch (e) {
      notificationData.body = event.data.text() || 'New update available!';
    }
  }
  const notificationPromise = self.registration.showNotification(
    notificationData.title || NOTIFICATION_TITLE,
    notificationData
  );
  event.waitUntil(notificationPromise);
});

// Handle notification click events
self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  if (event.action === 'view') {
    event.waitUntil(
      clients.openWindow('https://basetrello-fe.onrender.com')
    );
  } else if (event.action === 'dismiss') {
  } else {
    event.waitUntil(
      clients.matchAll({ type: 'window' }).then((clientList) => {
        for (const client of clientList) {
          if (client.url === '/' && 'focus' in client) {
            return client.focus();
          }
        }
        if (clients.openWindow) {
          return clients.openWindow('/');
        }
      })
    );
  }
});

// Handle notification close events
self.addEventListener('notificationclose', (event) => {
  self.registration.pushManager.getSubscription().then((subscription) => {
    if (subscription) {
      subscription.unsubscribe();
    }
  });
});

// Cache CSS and JS files with Stale-While-Revalidate strategy
registerRoute(
  ({ request }) => request.destination === 'style' || request.destination === 'script' || request.destination === 'worker',
  new StaleWhileRevalidate({
    cacheName: `${CACHE_NAME}-assets`,
    plugins: [
      new ExpirationPlugin({
        maxEntries: 100,
        maxAgeSeconds: 30 * 24 * 60 * 60, // 30 days
      }),
    ],
  })
);

// Cache images with CacheFirst strategy
registerRoute(
  ({ request }) => request.destination === 'image',
  new StaleWhileRevalidate({
    cacheName: `${CACHE_NAME}-images`,
    plugins: [
      new ExpirationPlugin({
        maxEntries: 60,
        maxAgeSeconds: 30 * 24 * 60 * 60, // 30 days
      }),
    ],
  })
);

// Network first strategy for API calls
registerRoute(
  ({ url }) => url.pathname.startsWith('/v1/api/'),
  new NetworkFirst({
    cacheName: `${CACHE_NAME}-api`,
    networkTimeoutSeconds: 10,
    plugins: [
      new ExpirationPlugin({
        maxEntries: 50,
        maxAgeSeconds: 5 * 60
      })
    ]
  })
);

// Process queued requests
const processBackgroundSync = async () => {
  try {
    const db = await openDatabase();
    const tx = db.transaction('requests', 'readwrite');
    const store = tx.objectStore('requests');
    
    const requests = await new Promise((resolve) => {
      const req = store.getAll();
      req.onsuccess = () => resolve(req.result);
      req.onerror = () => resolve([]);
    });
    
    for (const request of requests) {
      try {
        const headers = new Headers();
        if (request.headers) {
          Object.entries(request.headers).forEach(([key, value]) => {
            headers.append(key, value);
          });
        }
        
        let requestBody = null;
        if (request.body) {
          if (request.isBinary) {
            const binaryString = atob(request.body);
            const len = binaryString.length;
            const bytes = new Uint8Array(len);
            for (let i = 0; i < len; i++) {
              bytes[i] = binaryString.charCodeAt(i);
            }
            requestBody = bytes.buffer;
          } else {
            requestBody = request.body;
            const contentType = headers.get('content-type') || '';
            if (contentType.includes('application/json') && typeof requestBody === 'string') {
              try {
                requestBody = JSON.stringify(JSON.parse(requestBody));
              } catch (e) {
              }
            }
          }
        }
        
        const response = await fetch(request.url, {
          method: request.method,
          headers: headers,
          body: requestBody,
          credentials: 'include',
          redirect: 'follow'
        });
        
        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }
        
        await store.delete(request.id);
        const clients = await self.clients.matchAll({ type: 'window' });
        clients.forEach(client => {
          client.postMessage({
            type: 'SYNC_SUCCESS',
            url: request.url,
            method: request.method,
            timestamp: new Date().toISOString(),
            requestId: request.id
          });
        });
      } catch (error) {
      }
    }
    db.close();
  } catch (error) {
  }
};

// Open IndexedDB
const openDatabase = () => {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open('background-sync-queue', 1);
    request.onerror = () => reject(request.error);
    request.onsuccess = () => resolve(request.result);
    request.onupgradeneeded = (event) => {
      const db = event.target.result;
      if (!db.objectStoreNames.contains('requests')) {
        db.createObjectStore('requests', { keyPath: 'id', autoIncrement: true });
      }
    };
  });
};

// Configure background sync queue
const bgSyncPlugin = new BackgroundSyncPlugin('api-queue', {
  maxRetentionTime: 24 * 60,
  onSync: async ({queue}) => {
    try {
      await initIndexedDB();
    } catch (error) {
      return;
    }
    let entry;
    const MAX_RETRIES = 3;
    let retryCount = 0;
    while (entry = await queue.shiftRequest()) {
      try {
        if (retryCount >= MAX_RETRIES) {
          continue;
        }

        const clonedRequest = cloneRequestWithCredentials(entry.request);
        try {
          const response = await fetch(clonedRequest);
          if (!response.ok) {
            throw new Error(`HTTP error! status: ${response.status}`);
          }
          
          const clients = await self.clients.matchAll({ type: 'window' });
          clients.forEach(client => {
            client.postMessage({
              type: 'SYNC_SUCCESS',
              url: entry.request.url,
              method: entry.request.method,
              timestamp: new Date().toISOString()
            });
          });
          
          retryCount = 0; 
        } catch (error) {
          retryCount++;
          await queue.unshiftRequest(entry);
          throw error; 
        }
      } catch (error) {
        break;
      }
    }
  }
});

// Debug endpoint to inspect IndexedDB
const handleDebugRequest = async (event) => {
  const url = new URL(event.request.url);
  if (url.pathname === '/debug/sync-queue') {
    try {
      const db = await new Promise((resolve, reject) => {
        const request = indexedDB.open('workbox-background-sync', 1);
        request.onsuccess = () => resolve(request.result);
        request.onerror = () => reject(request.error);
      });
      
      const tx = db.transaction('requests', 'readonly');
      const store = tx.objectStore('requests');
      const requests = await new Promise((resolve) => {
        const req = store.getAll();
        req.onsuccess = () => resolve(req.result);
        req.onerror = () => resolve([]);
      });
      
      db.close();
      
      return new Response(JSON.stringify({
        queue: 'api-queue',
        count: requests.length,
        requests: requests.map(r => ({
          id: r.id,
          url: r.request.url,
          method: r.request.method,
          timestamp: r.timestamp
        }))
      }), {
        headers: { 'Content-Type': 'application/json' }
      });
    } catch (error) {
      return new Response(JSON.stringify({
        error: error.message,
        stack: error.stack
      }), {
        status: 500,
        headers: { 'Content-Type': 'application/json' }
      });
    }
  }
  return fetch(event.request);
};

// Initialize service worker
self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      await self.clients.claim();
      if ('sync' in self.registration) {
        const tags = await self.registration.sync.getTags();
        if (!tags.includes('sync-requests')) {
          await self.registration.sync.register('sync-requests');
        }
      }
    })()
  );
});

// Handle debug requests
self.addEventListener('fetch', (event) => {
  const url = new URL(event.request.url);
  if (url.pathname === '/debug/sync-queue') {
    event.respondWith(handleDebugRequest(event));
  }
});

// Handle write operations with background sync
registerRoute(
  ({url, request}) => {
    const isApi = url.pathname.startsWith('/v1/api/');
    const isWrite = ['POST', 'PUT', 'PATCH', 'DELETE'].includes(request.method);
    return isApi && isWrite;
  },
  new NetworkOnly({
    fetchOptions: {
      credentials: 'include'
    },
    plugins: [bgSyncPlugin]
  })
);

// Handle read operations with network first strategy
registerRoute(
  ({url, request}) => {
    const isApi = url.pathname.startsWith('/v1/api/');
    const isRead = request.method === 'GET';
    return isApi && isRead;
  },
  new NetworkFirst({
    cacheName: 'api-cache',
    networkTimeoutSeconds: 5,
    plugins: [
      new ExpirationPlugin({
        maxEntries: 50,
        maxAgeSeconds: 5 * 60 // 5 minutes
      })
    ]
  })
);

// Handle navigation requests with network first, falling back to offline page
const navigationHandler = async ({ event }) => {
  if (event.request.method !== 'GET') {
    return fetch(event.request);
  }
  try {
    const networkResponse = await fetch(event.request);
    const cache = await caches.open(CACHE_NAME);
    cache.put(event.request, networkResponse.clone());
    return networkResponse;
  } catch (error) {
    const cachedResponse = await caches.match(event.request);
    if (cachedResponse) {
      return cachedResponse;
    }
    
    if (event.request.mode === 'navigate') {
      return caches.match(OFFLINE_URL);
    }
    
    return new Response('You are offline, and we couldn\'t find this in the cache.', {
      status: 408,
      statusText: 'Offline',
      headers: { 'Content-Type': 'text/plain' }
    });
  }
};

registerRoute(({ request }) => request.mode === 'navigate', navigationHandler);

// Queue failed API requests
const queueRequest = async (request) => {
  try {
    const requestData = {
      url: request.url,
      method: request.method,
      headers: {},
      body: null,
      isBinary: false,
      timestamp: Date.now()
    };
    
    const headers = {};
    request.headers.forEach((value, key) => {
      if (!['content-length', 'content-encoding', 'host', 'connection', 'accept-encoding'].includes(key.toLowerCase())) {
        headers[key] = value;
      }
    });
    requestData.headers = headers;
    
    if (request.method !== 'GET' && request.method !== 'HEAD') {
      try {
        const requestClone = request.clone();
        const contentType = request.headers.get('content-type') || '';
        
        if (contentType.includes('application/json')) {
          try {
            const json = await requestClone.json();
            requestData.body = JSON.stringify(json);
          } catch (jsonError) {
            const text = await requestClone.text();
            requestData.body = text;
          }
        } 
        else if (contentType.includes('application/x-www-form-urlencoded') || 
                contentType.includes('multipart/form-data')) {
          const formData = await requestClone.formData();
          const formDataObj = {};
          for (const [key, value] of formData.entries()) {
            formDataObj[key] = value;
          }
          requestData.body = JSON.stringify(formDataObj);
        }
        else if (contentType.includes('text/')) {
          const text = await requestClone.text();
          requestData.body = text;
        }
        else {
          const arrayBuffer = await requestClone.arrayBuffer();
          if (arrayBuffer.byteLength > 0) {
            const bytes = new Uint8Array(arrayBuffer);
            let binary = '';
            for (let i = 0; i < bytes.byteLength; i++) {
              binary += String.fromCharCode(bytes[i]);
            }
            const base64String = btoa(binary);
            requestData.body = base64String;
            requestData.isBinary = true;
          } else {
          }
        }
      } catch (error) {
      }
    }
    
    const db = await openDatabase();
    const tx = db.transaction('requests', 'readwrite');
    const store = tx.objectStore('requests');
    
    const addRequest = new Promise((resolve, reject) => {
      const req = store.add(requestData);
      req.onsuccess = () => {
        resolve(req.result);
      };
      req.onerror = (event) => {
        reject(event.target.error);
      };
    });
    
    await addRequest;
    await tx.complete;
    db.close();
    
    if ('sync' in self.registration) {
      try {
        await self.registration.sync.register('sync-requests');
      } catch (error) {
      }
    }
    
    return true;
  } catch (error) {
    return false;
  }
};

// Create a clone of the request with its body preserved
const cloneRequest = async (request) => {
  if (request.method === 'GET' || request.method === 'HEAD') {
    return request.clone();
  }
  
  if (request.body === null) {
    return new Request(request.url, {
      method: request.method,
      headers: request.headers,
      credentials: request.credentials,
      cache: request.cache,
      redirect: request.redirect,
      referrer: request.referrer,
      referrerPolicy: request.referrerPolicy,
      integrity: request.integrity,
      keepalive: request.keepalive,
      mode: request.mode
    });
  }
  
  try {
    const requestClone = request.clone();
    const body = await requestClone.arrayBuffer();
    const newRequest = new Request(request.url, {
      method: request.method,
      headers: request.headers,
      body: body.byteLength > 0 ? body : undefined,
      credentials: request.credentials,
      cache: request.cache,
      redirect: request.redirect,
      referrer: request.referrer,
      referrerPolicy: request.referrerPolicy,
      integrity: request.integrity,
      keepalive: request.keepalive,
      mode: request.mode
    });
    
    return newRequest;
    
  } catch (error) {
    return new Request(request.url, {
      method: request.method,
      headers: request.headers,
      credentials: request.credentials,
      cache: request.cache,
      redirect: request.redirect,
      referrer: request.referrer,
      referrerPolicy: request.referrerPolicy,
      integrity: request.integrity,
      keepalive: request.keepalive,
      mode: request.mode
    });
  }
};

// Handle API requests with offline support
const handleApiRequest = async (event) => {
  const originalRequest = event.request;
  const url = new URL(originalRequest.url);
  const method = originalRequest.method;
  
  if (method === 'GET') {
    try {
      const fetchRequest = await cloneRequest(originalRequest);
      const networkResponse = await fetch(fetchRequest);
      
      if (networkResponse.ok) {
        const responseToCache = networkResponse.clone();
        const cacheRequest = await cloneRequest(originalRequest);
        caches.open(API_CACHE).then(cache => cache.put(cacheRequest, responseToCache));
        return networkResponse;
      }
      const cacheRequest = await cloneRequest(originalRequest);
      const cachedResponse = await caches.match(cacheRequest);
      if (cachedResponse) {
        return cachedResponse;
      }
      throw new Error(`HTTP error! status: ${networkResponse.status}`);
    } catch (error) {
      const cacheRequest = await cloneRequest(originalRequest);
      const cachedResponse = await caches.match(cacheRequest);
      if (cachedResponse) {
        return cachedResponse;
      }
      throw error;
    }
  }
  
  if (['POST', 'PUT', 'PATCH', 'DELETE'].includes(method)) {
    try {
      const fetchRequest = await cloneRequest(originalRequest);
      const response = await fetch(fetchRequest);
      
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      
      return response;
    } catch (error) {
      const queueRequestClone = await cloneRequest(originalRequest);
      const queued = await queueRequest(queueRequestClone);
      
      if (queued) {
        return new Response(JSON.stringify({
          status: 'queued',
          message: 'Request queued for later sync',
          timestamp: new Date().toISOString(),
          originalUrl: url.pathname,
          method: method
        }), {
          status: 202,
          headers: { 'Content-Type': 'application/json' }
        });
      }
      
      throw new Error('Failed to queue the request');
    }
  }
  
  return fetch(request);
};

// Main fetch event handler
self.addEventListener('fetch', (event) => {
  const url = new URL(event.request.url);
  const isApiRequest = url.pathname.startsWith('/v1/api/');
  
  if (url.pathname === '/debug/sync-queue') {
    return;
  }
  
  if (!isApiRequest || 
      event.request.url.startsWith('chrome-extension://') || 
      event.request.url.includes('sockjs') ||
      event.request.url.includes('socket.io')) {
    return;
  }
  
  if (isApiRequest) {
    event.respondWith(handleApiRequest(event));
    return;
  }
  
  if (event.request.mode === 'navigate') {
    event.respondWith(navigationHandler({ event }));
    return;
  }
  
  if (event.request.method === 'GET') {
    event.respondWith(
      caches.match(event.request).then(cachedResponse => {
        const fetchPromise = fetch(event.request).then(networkResponse => {
          if (networkResponse.ok) {
            const responseToCache = networkResponse.clone();
            caches.open(CACHE_NAME)
              .then(cache => cache.put(event.request, responseToCache));
          }
          return networkResponse;
        });
        
        return cachedResponse || fetchPromise.catch(() => {
          if (event.request.headers.get('accept')?.includes('text/html')) {
            return caches.match(OFFLINE_URL);
          }
          return new Response('You are offline', {
            status: 408,
            statusText: 'Offline',
            headers: { 'Content-Type': 'text/plain' }
          });
        });
      })
    );
  }
});
